        {"구절":"엡 5:8", "연결점":"너희가 전에는 어둠이더니 이제는 주 안에서 빛이라", "구분":"신약"},
        {"구절":"요일 2:8", "연결점":"어둠이 지나가고 참빛이 이미 비취고 있음이니라", "구분":"신약"}
