        {"새찬송가":"496", "통일찬송가":"343", "제목":"내 주여 뜻대로", "선정이유":"보내시는 하나님의 뜻에 순종하는 삶"},
        {"새찬송가":"357", "통일찬송가":"432", "제목":"이 세상에 근심된 일이", "선정이유":"어둠의 세상에 보냄받은 사명"},
        {"새찬송가":"497", "통일찬송가":"341", "제목":"나 같은 죄인 살리신", "선정이유":"은혜의 이름을 가진 요한처럼 은혜를 증거함"}
