        {"새찬송가":"461", "통일찬송가":"336", "제목":"한 이레 동안 주 은혜", "선정이유":"끊이지 않는 은혜의 연속"},
        {"새찬송가":"460", "통일찬송가":"396", "제목":"지금까지 지내온 것", "선정이유":"은혜 위에 은혜로 살아온 삶"}
