        {"상황":"은혜를 빌미로 방종하는 분", "성경원리":"은혜와 '진리'가 함께 왔다. 은혜는 진리를 폐하지 않는다. 참된 은혜는 거룩함을 향한 동력", "실제적용":"은혜는 죄를 허락하는 것이 아니라 죄에서 자유케 하는 능력이다. 은혜 안에서 거룩을 추구하라"},
        {"상황":"구약과 신약의 관계가 혼란스러운 분", "성경원리":"율법은 모세를 통해, 은혜와 진리는 예수를 통해 왔다. 대립이 아닌 완성의 관계", "실제적용":"구약은 예수님을 알기 위한 배경이다. 구약을 읽을 때 그리스도를 찾으라. 그때 구약이 살아난다"}
