        {"구분":"야곱의 하나님 대면", "내용":"창 32:30 하나님을 대면하여 보았으나 생명이 보전됨", "그리스도연결":"그리스도 안에서 하나님을 대면하되 생명을 얻게 됨 (요 14:6-9)"}
