        {"새찬송가":"85", "통일찬송가":"85", "제목":"구주를 생각만 해도", "선정이유":"하나님을 보여주신 독생자에 대한 사랑"},
        {"새찬송가":"115", "통일찬송가":"115", "제목":"기쁘다 구주 오셨네", "선정이유":"보이지 않는 하나님이 보이는 분으로 오신 기쁨"}
