        {"교리":"겸손의 극치", "설명":"요한의 자기 낮춤은 자기비하가 아닌 그리스도의 높으심에 대한 정확한 인식. 그리스도를 높이 볼수록 자기를 낮추게 됨", "관련구절":"요 3:30, 사 6:5, 욥 42:5-6, 빌 3:7-8"},
        {"교리":"종의 신학", "설명":"가장 천한 종의 역할도 감당 못하겠다는 고백은 그리스도와 인간 사이의 무한한 간격을 선언. 이 간격을 그리스도가 성육신으로 건너오심", "관련구절":"빌 2:7, 막 10:45, 요 13:5, 사 53:3"}
