        {"영어원문":"John was the greatest prophet, yet thought himself unworthy of the lowest service to Christ.", "한국어번역":"요한은 가장 위대한 선지자였으나 그리스도를 위한 가장 낮은 섬김도 감당 못하겠다고 여겼다.", "핵심통찰":"가장 위대한 자가 가장 낮아지는 것이 참된 위대함"},
        {"영어원문":"The more we know of Christ, the more we shall see our own unworthiness.", "한국어번역":"그리스도를 더 알수록 우리 자신의 부족함을 더 많이 보게 될 것이다.", "핵심통찰":"그리스도를 아는 것이 참된 겸손의 시작"}
