        {"대지":"2대지: 베다니에서 (가난한 자의 집)", "내용":"'베다니'는 '가난한 자의 집'이라는 뜻. 가난한 곳에서 부요한 복음이 선포됨. 하나님의 역설", "예화_적용":"가장 가난한 마을 이름이 '가난한 자의 집'이지만 이곳에서 가장 부요한 복음이 선포되었다"},
        {"대지":"3대지: 요한이 세례 주던 곳 (계속된 사역)", "내용":"미완료 시제 '에밥티젠'은 요한이 계속적으로 세례를 주고 있었음을 나타냄. 충실한 일상적 사역 가운데 하나님의 역사가 나타남", "예화_적용":"위대한 사건은 대부분 평범한 일상의 충실함 가운데서 일어난다"},
        {"대지":"결론", "내용":"하나님은 예루살렘 성전이 아닌 요단강 변방에서, 화려한 의식이 아닌 소박한 세례에서, 종교 지도자가 아닌 광야의 소리를 통해 일하셨다. 하나님은 오늘도 예상치 못한 곳에서 일하신다", "예화_적용":"당신의 작은 일터, 작은 교회, 작은 섬김의 자리가 하나님의 위대한 역사의 현장이 될 수 있다"}
