        {"대지":"서론", "내용":"요한은 하나님으로부터 직접 메시아를 알아보는 기준을 받았다. 성령이 내려와 머무는 자 — 그가 바로 성령으로 세례를 주시는 메시아이다", "예화_적용":"의사가 병을 진단할 때 증상만 보지 않고 정밀검사를 한다. 하나님은 요한에게 메시아를 정확히 식별할 수 있는 '영적 정밀검사' 기준을 주셨다"},
        {"대지":"1대지: 하나님의 파송 (나를 보내신 그이가)", "내용":"요한의 세례 사역은 하나님의 직접적 파송에 의한 것이었다. 자원한 것이 아닌 보냄 받은 것이다", "예화_적용":"대사가 외국에 파견되면 자기 의견이 아닌 본국 정부의 뜻을 전한다. 요한은 하나님의 대사로서 하나님이 주신 메시지를 전했다"},
        {"대지":"2대지: 하나님의 기준 (성령이 머무는 것을 보거든)", "내용":"메시아 식별의 기준은 인간적 판단이 아닌 하나님이 주신 표징이었다. 성령의 영구적 임재가 메시아의 표지이다", "예화_적용":"위조지폐를 감별할 때 직감이 아닌 정확한 기준(워터마크, 은선 등)으로 판별한다. 영적 분별도 감정이 아닌 하나님의 말씀이라는 기준이 필요하다"},
        {"대지":"3대지: 하나님의 약속 (성령으로 세례를 주는 이)", "내용":"예수님은 물이 아닌 성령으로 세례를 주신다. 이는 외적 정결이 아닌 내적 변화, 곧 중생을 의미한다", "예화_적용":"세탁기가 옷의 겉을 깨끗이 하듯 물세례는 외적 표현이다. 그러나 성령세례는 사람의 마음 자체를 새롭게 한다. 진정한 변화는 안에서부터 시작된다"},
        {"대지":"결론", "내용":"성령으로 세례 주시는 예수님은 오늘도 우리의 마음을 변화시키신다. 외적 종교 행위에 머물지 말고 성령의 내적 역사를 경험하라", "예화_적용":"오늘 말씀을 통해 받은 감동을 기도로 고백하라. 성령님 저를 변화시켜 주소서 — 이 고백이 성령세례의 열매를 맺게 할 것이다"}
