        {"새찬송가":"410", "통일찬송가":"361", "제목":"이 몸에 소망 무어냐", "선정이유":"반석이신 그리스도 위에 세워진 새 정체성의 고백"},
        {"새찬송가":"389", "통일찬송가":"348", "제목":"주 예수 대문 밖에", "선정이유":"예수님의 시선과 부르심에 응답하여 문을 여는 결단"},
        {"새찬송가":"288", "통일찬송가":"273", "제목":"반석 위에 내가 섰으니", "선정이유":"반석(게바/베드로)의 의미와 직결되는 찬송"}
