    표8_상담적용: [
        {"상황":"성경의 권위를 의심하는 분", "성경원리":"빌립은 '모세가 율법에 기록하였고 선지자가 기록한 그이'라고 성경에 호소했다. 수백 년에 걸친 수십 명의 기자가 기록한 예언이 한 사람에게서 성취된 것은 성경의 신뢰성을 보여준다", "실제적용":"메시아 예언과 성취 목록을 만들어 직접 확인해보라. 예: 출생지(미 5:2→마 2:1), 동정녀 탄생(사 7:14→마 1:18-23), 고난(사 53→마 27장). 증거를 직접 확인하라"},
        {"상황":"다른 사람에게 전도할 말이 없는 분", "성경원리":"빌립의 전도는 두 가지 요소로 구성되었다: 성경적 근거와 개인적 만남. 이 두 가지면 충분하다", "실제적용":"이 두 문장을 연습하라: (1) '성경에 이런 약속이 있는데...' (2) '내가 경험해보니 정말이야.' 이것이 빌립의 전도법이다"},
        {"상황":"예수님이 정말 메시아인지 의심하는 분", "성경원리":"빌립은 구약의 증거를 통해 예수님이 메시아임을 확신했다. 감정이 아닌 말씀의 증거에 기초한 확신이 필요하다", "실제적용":"요한복음 20:31을 읽으라: '이것을 기록함은 너희로 예수께서 하나님의 아들 그리스도이심을 믿게 하려 함이요.' 요한복음을 증거의 눈으로 읽어보라"}
    ],
