    표8_상담적용: [
        {"상황":"오랜 시간 변화가 없어 낙심한 성도", "성경원리":"46년의 건축도 하나님의 3일 앞에서는 아무것도 아니다. 하나님은 순간에 역사하실 수 있다. 긴 기다림이 불가능을 의미하지 않는다", "실제적용":"하나님의 때에 대한 신뢰를 회복하게 한다. 갈라디아서 6:9을 함께 읽으며, 포기하지 않으면 때가 이르매 거두리라는 약속을 붙잡게 한다"},
        {"상황":"하나님의 말씀을 이해하지 못해 답답한 성도", "성경원리":"유대인들도 예수님의 말씀을 바로 이해하지 못했다. 말씀의 이해는 때에 따라 점진적으로 이루어진다. 지금 이해되지 않는 것이 나중에 밝아질 수 있다", "실제적용":"이해되지 않는 말씀을 억지로 해석하려 하지 말고, 기도하며 반복해서 읽게 한다. 성령의 조명을 구하는 기도를 가르친다"},
        {"상황":"인간적 기준으로 하나님의 역사를 판단하는 성도", "성경원리":"유대인들은 46년의 건축 경험으로 3일의 재건을 불가능하다 판단했다. 인간의 경험과 논리로 하나님의 역사를 제한하면 안 된다", "실제적용":"지난 삶에서 불가능하다 생각했으나 이루어진 일들을 목록으로 적어보게 한다. 하나님의 전능하심에 대한 경험적 증거를 자신의 삶에서 발견하게 한다"}
    ],

