        {"새찬송가":"288", "통일찬송가":"321", "제목":"내 주를 가까이 하게 함은", "선정이유":"피상적 믿음을 넘어 인격적 만남으로"},
        {"새찬송가":"495", "통일찬송가":"422", "제목":"내 영혼아 이제 깨어", "선정이유":"영적 각성을 통해 깊은 믿음으로 나아감"},
        {"새찬송가":"440", "통일찬송가":"385", "제목":"나는 예수 따라가는", "선정이유":"구경꾼이 아닌 따르는 자로의 결단"}
