        {"대지":"결론", "내용":"밤에 불완전한 고백을 가지고 찾아와도 괜찮다. 예수님은 어둠 속에서 찾아오는 영혼을 절대 물리치지 않으신다. 지금 당신의 자리에서, 당신이 아는 만큼, 예수님께 나아가라", "예화_적용":"요한복음 6:37 — '내게 오는 자를 내가 결코 내어쫓지 아니하리라'"}
