    표2_역사적배경: [
        {"항목":"아노덴의 이중 의미", "내용":"아노덴은 '위에서부터'와 '다시/새로'라는 두 가지 의미를 가진다. 니고데모는 '다시'로 이해하여 육체적 재탄생을 생각했으나, 예수님의 의도는 '위에서부터' 즉 하나님으로부터의 영적 탄생이었다", "목회적활용":"영적 진리는 육적 관점으로는 이해할 수 없다"},
        {"항목":"유대교의 개종 관념", "내용":"유대 전통에서 이방인이 유대교로 개종하면 '새로 태어난 아기와 같다'고 했다. 그러나 예수님은 이미 유대인인 니고데모에게도 거듭남이 필요하다고 하셨으니 이것은 혁명적 선언이었다", "목회적활용":"종교적 소속이 아닌 영적 변화가 구원의 조건이다"},
        {"항목":"하나님 나라의 개념", "내용":"유대인들은 하나님 나라를 로마로부터의 정치적 해방과 이스라엘의 회복으로 기대했다. 그러나 예수님이 말씀하신 하나님 나라는 영적 통치와 변화의 나라이다", "목회적활용":"하나님 나라는 정치적 혁명이 아니라 영적 혁명이다"}
    ],

    표3_신학적의미: [
        {"교리":"중생(Regeneration)", "설명":"거듭남(중생)은 성령에 의한 영적 새 탄생으로, 인간의 노력이나 결단이 아닌 하나님의 주권적 사역이다. 이것은 구원론의 가장 핵심적 교리 중 하나이다", "관련구절":"딛 3:5, 벧전 1:3, 벧전 1:23"},
        {"교리":"하나님 나라의 조건", "설명":"하나님 나라에 들어가기 위한 조건은 율법 준수, 할례, 민족적 소속이 아니라 오직 거듭남이다. 이것은 유대교의 구원론을 완전히 전복하는 선언이다", "관련구절":"마 18:3, 갈 6:15, 고후 5:17"},
        {"교리":"전적 무능(Total Inability)", "설명":"거듭나지 않으면 하나님 나라를 '볼 수조차' 없다는 것은, 자연적 인간의 영적 무능을 선언한다. 인간은 스스로 구원에 이를 수 없으며, 하나님의 은혜가 절대적으로 필요하다", "관련구절":"롬 8:7-8, 고전 2:14, 엡 2:1"}
    ],

    표4_예표론: [
        {"구분":"거듭남의 개념", "내용":"에스겔의 새 마음과 새 영의 약속처럼(겔 36:26-27), 거듭남은 구약에서 이미 예고된 종말론적 사건이다", "그리스도연결":"그리스도 안에서 새 창조가 이루어진다 — 이전 것은 지나갔으니 보라 새 것이 되었도다 (고후 5:17)"},
        {"구분":"하나님 나라를 봄", "내용":"모세가 가나안을 바라만 보고 들어가지 못한 것처럼(신 34:4), 거듭나지 않은 자는 하나님 나라를 볼 수는 있으나 들어가지 못한다", "그리스도연결":"그리스도를 통해 하나님 나라에 들어가는 길이 열렸다 (요 14:6)"},
        {"구분":"위에서부터의 탄생", "내용":"아담이 하나님의 숨(루아흐)을 받아 생령이 된 것처럼(창 2:7), 거듭남은 하나님의 영에 의한 새로운 생명의 부여이다", "그리스도연결":"마지막 아담이신 그리스도는 살려주는 영이시다 (고전 15:45)"}
    ],

    표5_매튜헨리: [
        {"영어원문":"Verily, verily — this solemn preface shows that something of great weight and importance is coming. Christ demands attention.", "한국어번역":"진실로 진실로 — 이 엄숙한 서두는 매우 중대하고 중요한 것이 올 것임을 보여준다. 그리스도께서 주목을 요구하신다.", "핵심통찰":"이중 아멘은 그리스도의 절대적 권위로 선포되는 진리이다"},
        {"영어원문":"Except a man be born again, he cannot see the kingdom of God — this was said to Nicodemus, a learned Pharisee, showing that the best education cannot make a man a Christian.", "한국어번역":"사람이 거듭나지 아니하면 하나님 나라를 볼 수 없다 — 이것은 학식 있는 바리새인 니고데모에게 말씀하신 것으로, 최고의 교육도 사람을 그리스도인으로 만들 수 없음을 보여준다.", "핵심통찰":"교육이나 종교적 훈련으로 구원을 얻을 수 없다"},
        {"영어원문":"The new birth is absolutely necessary to our happiness. Without it we cannot see the kingdom of God — not only not enter it, but not even see it.", "한국어번역":"새 탄생은 우리의 행복에 절대적으로 필요하다. 그것 없이는 하나님 나라를 볼 수 없다 — 들어가지 못할 뿐 아니라 보지도 못한다.", "핵심통찰":"거듭남 없이는 하나님 나라를 인식조차 할 수 없다"}
    ],

    표6_설교자료: [
        {"대지":"제목", "내용":"거듭나야 하리라 — 구원의 유일한 길", "예화_적용":"율법도, 지식도, 지위도 대체할 수 없는 것이 거듭남이다"},
        {"대지":"서론", "내용":"니고데모는 표적에 대해 이야기하려 했으나, 예수님은 곧바로 핵심을 찌르셨다. '거듭나지 아니하면 하나님 나라를 볼 수 없다.' 이것은 모든 종교적 장식을 벗기는 선언이었다. 문제는 무엇을 하느냐가 아니라 무엇이 되느냐이다", "예화_적용":"애벌레가 아무리 노력해도 날 수 없다 — 날려면 나비가 되어야 한다. 변화가 아닌 변태(變態, metamorphosis)가 필요하다"},
        {"대지":"1대지: 진실로 진실로 — 절대적 선언 (권위)", "내용":"이중 아멘은 구약 전통에서 하나님만이 하시는 맹세의 형식이다. 예수님이 이 형식을 사용하신 것은 신적 권위로 선포하시는 것이다. 이것은 제안이 아니라 선언이다", "예화_적용":"의사가 '수술이 필요합니다'라고 할 때 이것은 의견이 아니라 진단이다 — 거듭남은 선택 사항이 아닌 필수이다"},
        {"대지":"2대지: 거듭나지 아니하면 — 절대적 조건 (필요)", "내용":"'아니하면'은 예외가 없음을 의미한다. 바리새인도, 관원도, 선생도 거듭나야 한다. 어떤 종교적 성취도, 도덕적 노력도, 사회적 지위도 거듭남을 대체할 수 없다", "예화_적용":"비행기 탑승권 없이는 아무리 좋은 옷을 입어도 비행기에 탈 수 없는 것처럼, 거듭남 없이는 하나님 나라에 들어갈 수 없다"},
        {"대지":"3대지: 하나님 나라를 볼 수 없다 — 절대적 결과 (현실)", "내용":"거듭나지 않으면 하나님 나라를 '볼 수조차' 없다. 이것은 들어가지 못하는 것보다 더 심각하다 — 존재 자체를 인식하지 못하는 것이다. 영적 눈이 열려야 영적 현실을 볼 수 있다", "예화_적용":"색맹인 사람이 빨간 꽃을 볼 수 없는 것은 꽃이 없어서가 아니라 볼 수 없기 때문인 것처럼, 거듭나지 못한 영혼은 하나님 나라를 인식하지 못한다"},
        {"대지":"결론", "내용":"오늘 예수님이 당신에게 묻고 계신다. '거듭났느냐?' 종교 생활의 연수가 아니라, 하나님으로부터의 새 탄생이 있었느냐를. 지금 이 자리에서 성령에 의한 거듭남의 은혜를 구하자", "예화_적용":"존 웨슬리가 올더스게이트에서 마음이 이상하게 뜨거워지는 경험을 한 것 — 오래된 성직자에게도 거듭남의 순간이 있었다"}
    ],

