        {"상황":"나이가 많아 새 시작이 어렵다고 느끼는 장년 성도", "성경원리":"아브라함은 75세에, 모세는 80세에 새 사명을 시작했다. 하나님의 역사에 나이 제한은 없다", "실제적용":"성경의 만학도형 인물들의 사례를 함께 살펴보고, 현재 시점에서 가능한 영적 도전을 찾게 한다"},
        {"상황":"영적 진리를 이해하기 어려운 성도", "성경원리":"니고데모는 이스라엘의 선생이었으나 거듭남을 이해하지 못했다. 영적 진리는 지적 능력이 아닌 성령의 조명으로 이해된다", "실제적용":"이해를 강요하지 말고, 기도하며 말씀을 반복 읽게 한다. 성령의 가르치심을 구하는 구체적 기도를 안내한다"}
