        {"구분":"홍해 도하", "내용":"이스라엘이 홍해를 통과(물)하고 구름 기둥(영)의 인도를 받은 것처럼(출 14장), 구원은 물과 영의 이중 사역을 통해 이루어진다", "그리스도연결":"고린도전서 10:1-2 — 모세에게 세례를 받음으로 물과 구름 안에서"},
        {"구분":"성막의 물두멍", "내용":"제사장이 성막에 들어가기 전 물두멍(놋대야)에서 손발을 씻었듯이(출 30:18-20), 하나님의 임재에 나아가기 위해서는 정결이 필요했다", "그리스도연결":"그리스도의 피로 정결케 되어 하나님 앞에 나아간다 (히 10:22)"}
