        {"상황":"세례를 아직 받지 않은 믿는 자", "성경원리":"물과 성령이 함께 언급된 것은 내적 믿음의 외적 고백(세례)이 중요함을 보여준다. 세례는 구원의 조건이 아니라 구원의 고백이다", "실제적용":"세례의 성경적 의미를 설명하고, 세례를 통해 믿음을 공개적으로 고백하도록 격려한다"},
        {"상황":"성령 체험이 무엇인지 모르는 성도", "성경원리":"성령의 사역은 새 마음, 새 욕망, 하나님에 대한 사랑, 죄에 대한 민감함으로 나타난다. 반드시 특별한 체험이 아니어도 성령의 열매(갈 5:22-23)로 확인할 수 있다", "실제적용":"성령의 열매를 점검하며, 일상에서의 성령의 사역을 인식하게 한다. 특별한 체험보다 삶의 변화에 주목하게 한다"}
