        {"원어":"ὑμᾶς (휘마스)", "의미_문법":"너희를 — 인칭대명사, 2인칭 복수, '너'에서 '너희'로 확대됨", "설교포인트":"거듭남은 니고데모만이 아닌 모든 사람에게 해당되는 보편적 필요"},
        {"원어":"ἄνωθεν (아노덴)", "의미_문법":"위에서부터/다시 — 부사, 3절과 동일, 여기서는 '위에서부터'의 의미가 더 강조됨", "설교포인트":"거듭남의 기원은 땅이 아닌 하늘, 인간이 아닌 하나님이시다"}
