        {"대지":"서론", "내용":"예수님은 니고데모의 놀라움을 이해하셨다. 그래서 '기이히 여기지 말라'고 하셨다. 그러나 이해가 되든 안 되든, 거듭나야 한다(데이)는 사실은 변하지 않는다. 이것은 권고가 아니라 하나님의 절대 명령이다", "예화_적용":"의사가 '수술해야 합니다'라고 할 때 환자가 놀라더라도 수술의 필요성은 변하지 않는다"},
        {"대지":"1대지: 기이히 여기지 말라 — 놀라움의 극복 (수용)", "내용":"영적 진리가 인간의 상식과 맞지 않을 수 있다. 그러나 하나님의 진리는 인간 논리에 기초하지 않는다. 놀라움에 머무르면 진리를 놓치게 된다", "예화_적용":"지구가 둥글다는 사실이 처음에는 상식에 반했으나 진리였듯이, 거듭남도 상식을 초월하나 진리이다"},
        {"대지":"2대지: 너희가 — 보편적 명령 (모두)", "내용":"'너'에서 '너희'로의 전환은 중요하다. 거듭남은 니고데모만이 아니라 모든 사람에게 해당된다. 바리새인도, 세리도, 남자도, 여자도, 늙은이도, 젊은이도 — 모두 거듭나야 한다", "예화_적용":"만유인력은 모든 물체에 적용되듯이, 거듭남의 필요는 모든 인간에게 적용된다"},
        {"대지":"3대지: 해야 하리라 — 신적 필연 (순종)", "내용":"데이(~해야 한다)는 하나님의 계획에서 빠질 수 없는 필수 사항이다. 거듭남은 선택 사항이 아니다. 하나님이 정하셨고, 하나님이 이루신다. 우리는 그 앞에 순종할 뿐이다", "예화_적용":"중력을 거스를 수 없듯이, 하나님의 필연을 거스를 수 없다 — 겸손히 순종하는 것이 지혜이다"},
        {"대지":"결론", "내용":"놀라움을 넘어 순종으로 나아가자. 이해되지 않아도 괜찮다. 하나님이 '해야 한다'고 하셨으면 그것으로 충분하다. 지금 성령의 거듭나게 하시는 역사를 구하라", "예화_적용":"마리아의 고백 — '말씀대로 내게 이루어지이다' (눅 1:38) — 이해 이전에 순종"}
