        {"항목":"유대 묵시문학 전통", "내용":"에녹서, 에스라4서 등 유대 묵시문학에서 인자는 하늘에서 내려와 심판하는 메시아로 묘사된다. 이 전통을 니고데모도 알고 있었을 것이다", "목회적활용":"니고데모가 알던 메시아 지식을 넘어서는 계시가 예수님 안에 있다"},
        {"항목":"하늘과 땅의 연결", "내용":"고대 유대 사상에서 하늘에 올라가 하나님의 비밀을 보고 온 자는 모세, 엘리야 정도였다. 예수님은 이들과 달리 본래 하늘에서 내려오신 분임을 선언하신다", "목회적활용":"예수님은 하늘의 비밀을 전달하는 사자가 아니라 하늘 자체에서 오신 분이시다"}
