        {"새찬송가":"305", "통일찬송가":"251", "제목":"나는 갈 곳 모르지만", "선정이유":"믿음으로 영생의 길을 가는 확신"},
        {"새찬송가":"288", "통일찬송가":"235", "제목":"어려운 일 당할 때", "선정이유":"어떤 상황에서도 믿음으로 영생을 붙잡음"},
        {"새찬송가":"486", "통일찬송가":"430", "제목":"참 아름다워라", "선정이유":"영생의 아름다운 소망"}
