        {"항목":"실현된 종말론", "내용":"요한복음의 특징적 종말론으로 심판과 영생이 미래뿐 아니라 현재에 이미 실현되고 있다는 가르침이다. 이것을 '실현된 종말론(realized eschatology)'이라 한다", "목회적활용":"지금 이 순간의 믿음의 결단이 영원을 결정한다"}
