        {"원어":"μισεῖ (미세이)", "의미_문법":"미워하다 - 현재 능동. 지속적으로 미워함", "설교포인트":"악인은 빛을 지속적으로 미워한다. 이것은 습관적 태도이다"},
        {"원어":"ἐλεγχθῇ (엘렝크테)", "의미_문법":"드러나다, 책망받다 - 가정법 수동. 폭로되고 꾸짖음을 받다", "설교포인트":"빛은 숨겨진 악을 드러내고 책망하는 기능을 한다"},
        {"원어":"ἔρχεται (에르케타이)", "의미_문법":"오다 - 현재 직설법. 나아가다", "설교포인트":"빛으로 오지 않는다는 것은 의도적으로 그리스도를 거부하는 것이다"}
