        {"항목":"유대교의 도덕적 이원론", "내용":"쿰란 문서에서 빛의 영과 어둠의 영이 인간의 마음속에서 투쟁한다고 가르쳤다. 요한복음은 이 개념을 그리스도 중심으로 재해석한다", "목회적활용":"빛과 어둠의 싸움은 내 마음 안에서도 일어나고 있다"},
        {"항목":"로마 시대의 야간 범죄", "내용":"로마 시대 도시에서 야간은 범죄가 횡행하는 시간이었다. 가로등이 없어 어둠이 범죄의 은폐처 역할을 했다", "목회적활용":"어둠은 죄의 은폐처이지만 하나님의 빛은 모든 어둠을 꿰뚫으신다"}
