        {"교리":"도덕적 책임", "설명":"빛으로 오지 않는 것은 의도적 선택이다. 이 선택에는 도덕적 책임이 따른다. 무지가 아닌 고의적 거부이다", "관련구절":"요 15:22, 약 4:17, 눅 12:47-48"}
