    표5_매튜헨리: [
        {"영어원문":"John also was baptizing in Aenon, near to Salim, because there was much water there.", "한국어번역":"요한도 살렘 가까운 애논에서 세례를 주니 거기 물이 많기 때문이었다.", "핵심통찰":"사역을 위해 적합한 환경을 찾는 것은 지혜이다"},
        {"영어원문":"John continued his baptizing even after Christ had begun to baptize, not in rivalry but in faithful continuance of his own calling.", "한국어번역":"그리스도께서 세례를 시작하신 후에도 요한은 계속 세례를 주었으니 경쟁이 아니라 자기 부르심에 대한 충실한 지속이었다.", "핵심통찰":"자기 부르심에 충실한 것이 겸손의 참된 표현이다"},
        {"영어원문":"People came and were baptized, showing that John's ministry still had effect and drew sincere seekers to repentance.", "한국어번역":"사람들이 와서 세례를 받았으니 요한의 사역이 여전히 효과가 있었고 진실한 구도자들을 회개로 이끌었다.", "핵심통찰":"충실한 사역은 열매를 계속 맺는다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"자기 자리에서 충실하게", "예화_적용":"세례요한의 겸손한 사역이 주는 교훈"},
        {"대지":"서론", "내용":"예수님이 이미 세례를 주고 계셨다. 사람들이 예수님께로 몰려가고 있었다. 그런데 세례요한은 자기 자리에서 묵묵히 세례를 계속하고 있었다. 비교하지 않고 자기 몫을 다하는 아름다운 모습이다", "예화_적용":"오케스트라에서 모든 악기가 지휘자만 바라보며 자기 파트를 충실히 연주할 때 아름다운 음악이 된다"},
        {"대지":"1대지: 애논에서 세례를 주니 (자기 자리에서)", "내용":"애논은 화려한 곳이 아니었다. 물이 많다는 실용적 이유로 선택된 곳이다. 요한은 적합한 장소에서 맡겨진 일을 했다", "예화_적용":"사역의 장소가 중요한 것이 아니라 그 자리에서 충실한 것이 중요하다"},
        {"대지":"2대지: 물이 많음이라 (준비된 환경)", "내용":"세례를 위해 물이 필요했고 하나님은 적합한 장소를 예비하셨다. 사역에 필요한 것을 하나님이 공급하신다", "예화_적용":"하나님은 사명을 주시면 사명을 수행할 환경도 준비해 주신다"},
        {"대지":"3대지: 사람들이 와서 세례를 받더라 (지속되는 열매)", "내용":"예수님께 사람들이 몰려가도 요한에게도 여전히 사람들이 왔다. 충실한 사역에는 하나님이 열매를 주신다", "예화_적용":"다른 사람의 사역과 비교하지 말라. 자기 자리에서 충실하면 열매는 하나님이 주신다"},
        {"대지":"결론", "내용":"세례요한의 위대함은 자기 자리에서 충실했다는 것이다. 더 큰 사역을 부러워하지 않고 맡겨진 사역을 묵묵히 수행했다. 우리도 각자의 자리에서 충실합시다", "예화_적용":"모든 자리에서 충실한 것이 가장 위대한 사역이다"}
    ],
