        {"구절":"요 4:2", "연결점":"예수께서 친히 세례를 주신 것이 아니요 — 세례의 위임", "구분":"신약"},
        {"구절":"행 19:3-5", "연결점":"요한의 세례로 세례를 받고 다시 주 예수의 이름으로 — 세례의 발전", "구분":"신약"},
        {"구절":"롬 6:3-4", "연결점":"세례를 받아 그의 죽으심과 합하여 장사된 것이니 — 세례의 의미", "구분":"신약"},
        {"구절":"고전 3:6-7", "연결점":"나는 심었고 아볼로는 물을 주었으되 — 각자의 역할", "구분":"신약"}
