        {"상황":"신앙 때문에 박해나 불이익을 걱정하는 분", "성경원리":"세례요한은 진리를 위해 투옥의 대가를 치렀다. 의를 위해 박해를 받는 자는 복이 있다(마 5:10)", "실제적용":"진리를 위한 대가를 두려워하지 말라. 하나님이 그 시간까지 주관하신다"},
        {"상황":"주어진 시간을 의미 있게 사용하고 싶은 분", "성경원리":"'아직' 자유로운 시간 동안 요한은 세례를 주며 사역했다. 시간은 제한되어 있다", "실제적용":"지금 할 수 있는 봉사와 사역에 시간을 투자하라. 은혜의 때는 영원하지 않다"}
