        {"구분":"욥의 고백", "내용":"욥 1:21 주신 이도 여호와시요 거두신 이도 여호와시니 — 주심과 거두심의 주권", "그리스도연결":"하나님의 주심과 거두심 모두를 받아들이는 것이 믿음이다"},
        {"구분":"다윗의 감사", "내용":"대상 29:14 모든 것이 주에게서 왔사오니 우리가 주의 손에서 받은 것으로 주께 드렸을 뿐이니이다", "그리스도연결":"우리가 드리는 것도 하나님께 받은 것을 돌려드리는 것이다"}
