    표5_매튜헨리: [
        {"영어원문":"A man can receive nothing except it be given him from heaven; this is the great principle that silences all jealousy and discontent.", "한국어번역":"하늘에서 주신바 아니면 사람이 아무것도 받을 수 없나니 이것이 모든 질투와 불만을 잠재우는 위대한 원리이다.", "핵심통찰":"하나님 주권의 인정이 질투를 이기는 비결이다"},
        {"영어원문":"John acknowledged that what he had was a gift from God, and therefore he could not grudge that God should give to another more abundantly.", "한국어번역":"요한은 자기가 가진 것이 하나님의 선물임을 인정했기에 하나님이 다른 이에게 더 풍성히 주시는 것을 시기할 수 없었다.", "핵심통찰":"내 것이 선물임을 알면 다른 이의 선물을 시기하지 않게 된다"},
        {"영어원문":"If God be glorified, no matter whether it be by me or by another; the main thing is that the work be done.", "한국어번역":"하나님이 영광받으시면 나를 통하든 다른 이를 통하든 상관없다. 중요한 것은 그 일이 이루어지는 것이다.", "핵심통찰":"사역의 목적은 하나님의 영광이지 나의 영광이 아니다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"하늘에서 주신 바 아니면", "예화_적용":"하나님 주권의 인정이 겸손의 시작이다"},
        {"대지":"서론", "내용":"제자들이 질투에 불타 보고했을 때 요한의 첫 마디가 이것이다. '하늘에서 주신바 아니면 사람이 아무것도 받을 수 없다.' 이 한 마디가 모든 질투와 비교의식을 잠재운다. 왜냐하면 모든 것이 하나님의 선물이기 때문이다", "예화_적용":"같은 부모에게서 다른 선물을 받은 형제가 서로의 선물을 시기할 필요가 있는가"},
        {"대지":"1대지: 하늘에서 주신바 (모든 것의 원천)", "내용":"능력, 사역, 열매, 인기 모두 하늘에서 온다. 내가 만들어낸 것이 아니다. 야고보서 1:17 각양 좋은 은사와 온전한 선물이 다 위로부터 내려온다", "예화_적용":"강의 물은 산에서 온다. 강이 자기 물을 자랑할 수 없듯이 우리도 받은 것을 자랑할 수 없다"},
        {"대지":"2대지: 사람이 아무것도 받을 수 없느니라 (인간의 한계)", "내용":"우덴(아무것도)은 절대적 부정이다. 하나님의 허락 없이는 아무것도 가질 수 없다. 이것은 겸손의 토대이다", "예화_적용":"빈손으로 태어나 빈손으로 떠나는 것이 인생이다. 가진 모든 것은 빌려 쓰는 것이다"},
        {"대지":"3대지: 요한의 겸손 (질투의 극복)", "내용":"이 원리를 인정하면 질투가 사라진다. 다른 사람이 더 많이 받은 것은 하나님의 주권적 결정이기 때문이다. 시기 대신 감사가 온다", "예화_적용":"왕이 신하에게 봉토를 나눠줄 때 신하들이 서로의 봉토를 시기하는 것은 왕의 결정을 불신하는 것이다"},
        {"대지":"결론", "내용":"오늘 당신이 가진 것은 무엇인가? 그것은 모두 하늘에서 주신 것이다. 감사하라. 그리고 다른 이가 받은 것도 하늘에서 준 것이니 기뻐하라", "예화_적용":"주어진 것에 감사하고 다른 이에게 주어진 것에 기뻐하는 것이 성숙한 믿음이다"}
    ],
