        {"구절":"요 19:11", "연결점":"위에서 주지 아니하셨더면 나를 해할 권한이 없었으리라 — 빌라도에게 주어진 권한", "구분":"신약"},
        {"구절":"빌 4:11-13", "연결점":"어떠한 형편에든지 자족하기를 배웠노니 — 받은 것으로의 만족", "구분":"신약"}
