        {"원어":"λαλεῖ (랄레이)", "의미_문법":"말하다 - 현재 능동. 계속적으로 말함", "설교포인트":"땅의 존재는 땅의 것밖에 말할 수 없지만 하늘의 존재는 하늘의 것을 말씀하신다"}
