        {"구분":"시내산의 하나님", "내용":"출 19:20 여호와께서 시내산 꼭대기에 강림하시고 — 하늘에서 땅으로의 강림", "그리스도연결":"그리스도의 성육신은 하나님이 위로부터 아래로 내려오신 궁극적 사건이다"},
        {"구분":"하늘의 만나", "내용":"출 16:4 내가 너희를 위하여 하늘에서 양식을 비같이 내리리라", "그리스도연결":"그리스도는 위로부터 내려온 참된 생명의 양식이시다 (요 6:51)"}
