        {"구절":"시 97:9", "연결점":"여호와여 주는 온 땅 위에 지존하시고 — 만물 위에 계심", "구분":"구약"},
        {"구절":"단 7:13-14", "연결점":"인자 같은 이가 와서 영원한 권세를 받았으니 — 만물 위의 권세", "구분":"구약"},
        {"구절":"요 8:23", "연결점":"너희는 아래서 났고 나는 위에서 났으며 — 위와 아래의 대비", "구분":"신약"},
        {"구절":"골 1:16-17", "연결점":"만물이 그에게 창조되되 — 그리스도의 만물 위의 주권", "구분":"신약"},
        {"구절":"엡 1:20-21", "연결점":"모든 정사와 권세와 능력과 주관하는 자 위에 뛰어나게 하시고 — 만물 위의 권세", "구분":"신약"},
        {"구절":"히 1:1-4", "연결점":"이 모든 날 마지막에 아들로 우리에게 말씀하셨으니 — 최종적 계시자", "구분":"신약"}
