        {"새찬송가":"393", "통일찬송가":"297", "제목":"나 맡은 본분은", "선정이유":"하나님의 진실하심 위에 맡겨진 사명을 수행"},
        {"새찬송가":"354", "통일찬송가":"282", "제목":"주 하나님 크시도다", "선정이유":"참되시고 크신 하나님을 찬양"},
        {"새찬송가":"543", "통일찬송가":"485", "제목":"주 하나님이 함께하시니", "선정이유":"참되신 하나님이 함께하시는 확신"}
