        {"원어":"Γαλιλαίαν (갈릴라이안)", "의미_문법":"갈릴리 - 고유명사. 북부 지역, 예수님의 주 사역지", "설교포인트":"갈릴리는 이방의 갈릴리(사 9:1)로 소외된 지역이었으나 예수님의 주 사역지가 되었다"},
        {"원어":"πάλιν (팔린)", "의미_문법":"다시 - 부사. 또다시, 재차", "설교포인트":"다시 갈릴리로 가신다는 것은 이전에도 그곳에서 사역하셨음을 보여준다"}
