    표2_역사적배경: [
        {"항목":"유대에서 갈릴리로의 이동 경로", "내용":"유대에서 갈릴리로 가는 데는 세 경로가 있었다. 요단강 동편, 요단강 서편, 사마리아 관통. 직선 거리는 사마리아를 통과하는 것이 가장 짧았다", "목회적활용":"하나님은 가장 효율적인 길이 아닌 가장 의미 있는 길로 인도하신다"},
        {"항목":"갈릴리의 사회적 위상", "내용":"갈릴리는 예루살렘 중심의 유대 사회에서 변방으로 취급되었다. '갈릴리에서 선지자가 나겠느냐'(요 7:52)는 멸시가 있었다", "목회적활용":"하나님은 중심부가 아닌 변방에서 큰 일을 행하신다"},
        {"항목":"예수님의 사역 패턴", "내용":"요한복음에서 예수님은 예루살렘(명절)과 갈릴리를 오가며 사역하셨다. 이 이동은 유대인과 이방인 모두에게 복음을 전하시려는 패턴이다", "목회적활용":"복음은 중심부에만 머무르지 않고 주변부로 확장된다"}
    ],
    표3_신학적의미: [
        {"교리":"하나님의 섭리적 인도", "설명":"유대를 떠나 갈릴리로 가시는 과정에서 사마리아를 통과하시게 되었다. 이 이동이 사마리아 여인과의 만남을 가능하게 했다. 모든 것이 하나님의 섭리 안에 있다", "관련구절":"롬 8:28, 잠 16:9, 잠 20:24"},
        {"교리":"복음의 확장", "설명":"유대에서 갈릴리로, 그 길에 사마리아가 있다. 이것은 행 1:8의 예루살렘-유대-사마리아-땅끝 선교 패턴의 예고이다", "관련구절":"행 1:8, 사 49:6, 마 28:19"},
        {"교리":"겸손한 사역", "설명":"종교 중심지 유대를 떠나 변방 갈릴리로 가시는 것은 그리스도의 겸손한 사역 방식을 보여준다", "관련구절":"사 42:1-3, 마 12:18-21, 빌 2:7"}
    ],
