        {"구분":"야곱의 하란행", "내용":"창 28:10 야곱이 브엘세바를 떠나 하란으로 갔다", "그리스도연결":"떠남의 여정에서 하나님을 만나게 된다. 예수님도 사마리아에서 여인을 만나셨다"},
        {"구분":"이스라엘의 광야 여정", "내용":"출 13:17-18 하나님이 블레셋 땅의 길이 가까워도 돌려 보내셨다", "그리스도연결":"하나님의 인도는 때로 우회하지만 그 길에 더 큰 목적이 있다"}
