    표5_매튜헨리: [
        {"영어원문":"He left Judea and departed again into Galilee; his work in Judea was done for the present, and Galilee called for his presence.", "한국어번역":"유대를 떠나 다시 갈릴리로 가셨으니 유대에서의 현재 사역은 마쳤고 갈릴리가 그의 임재를 요청하고 있었다.", "핵심통찰":"한 곳의 사역을 마치고 다른 곳으로 나아가시는 것이 사역의 패턴이다"},
        {"영어원문":"The withdrawal from Judea was not a retreat from danger, but a strategic advance toward a broader ministry.", "한국어번역":"유대에서의 철수는 위험으로부터의 후퇴가 아니라 더 넓은 사역을 향한 전략적 전진이었다.", "핵심통찰":"후퇴처럼 보이는 것이 실은 전진일 수 있다"},
        {"영어원문":"Providence ordered his journey through Samaria, that he might there meet with a poor sinful woman whom he had mercy in store for.", "한국어번역":"섭리가 그의 여정을 사마리아를 통과하도록 하셨으니 거기서 그가 자비를 준비해 두신 가난하고 죄 많은 여인을 만나게 하려 함이었다.", "핵심통찰":"모든 여정에는 하나님의 섭리적 만남이 준비되어 있다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"떠나심과 나아가심 — 하나님의 인도", "예화_적용":"유대를 떠나 갈릴리로 가시는 여정에 담긴 섭리"},
        {"대지":"서론", "내용":"인생에는 떠나야 할 때가 있다. 예수님은 유대를 떠나셨다. 그것은 패배가 아니었다. 더 큰 사역을 향한 이동이었다. 그리고 이 이동의 길목에서 역사상 가장 아름다운 만남이 기다리고 있었다", "예화_적용":"비행기가 활주로를 떠나야 하늘을 날 수 있듯이 떠남이 있어야 새로운 만남이 있다"},
        {"대지":"1대지: 유대를 떠나사 (떠남의 결단)", "내용":"아페켄(떠나다)은 강한 단어이다. 완전히 버리고 떠나셨다. 때로는 익숙한 곳을 떠나야 새 길이 열린다", "예화_적용":"편안한 곳에 머무르면 성장이 없다. 떠남은 성장의 시작이다"},
        {"대지":"2대지: 다시 갈릴리로 (돌아감의 의미)", "내용":"갈릴리는 예수님의 주 사역지였다. 다시 그곳으로 돌아가신다. 이것은 사역의 중심으로의 복귀이다", "예화_적용":"때로는 원점으로 돌아가야 다시 출발할 수 있다. 원점 회귀는 포기가 아니라 재정비이다"},
        {"대지":"3대지: 가실새 (여정 중의 만남)", "내용":"갈릴리로 가시는 길에 사마리아가 있었다. 목적지에 도착하기 전 여정 자체가 사역이 되었다. 이동 중에 가장 위대한 만남이 이루어졌다", "예화_적용":"목적지보다 여정이 중요할 때가 있다. 길에서 만나는 사람이 인생을 바꿀 수 있다"},
        {"대지":"결론", "내용":"하나님이 이끄시는 길을 신뢰하라. 떠남도, 이동도, 도착도 모두 하나님의 계획 안에 있다. 여정 자체를 즐기라", "예화_적용":"인생은 목적지가 아니라 여정이다. 그 여정에서 하나님을 만나라"}
    ],
