        {"상황":"인생의 방향이 불확실한 분", "성경원리":"예수님의 여정에는 하나님의 섭리가 있었다. 우회하는 것 같아도 하나님의 인도가 있다", "실제적용":"지금 어디로 가고 있는지 모르겠어도 하나님이 인도하고 계심을 신뢰하라"},
        {"상황":"이동과 변화가 잦아 안정감이 없는 분", "성경원리":"예수님도 유대와 갈릴리를 오가며 사역하셨다. 이동 자체가 사역의 일부였다", "실제적용":"장소의 안정보다 하나님과의 관계의 안정이 중요하다. 어디에 있든 하나님과 함께이면 안전하다"}
