        {"구절":"행 8:5-8", "연결점":"빌립이 사마리아에 내려가 전파하니 — 사마리아 복음화", "구분":"신약"},
        {"구절":"요 4:12", "연결점":"야곱보다 더 크니이까 — 여인의 질문", "구분":"신약"},
        {"구절":"히 11:21-22", "연결점":"야곱과 요셉의 믿음 — 족장들의 유산", "구분":"신약"}
